using IndieRun;
using System.Diagnostics;
using System.IO;
using System.Text.Json;
class Program
{
    static void Check(bool value,string message){if(!value)throw new Exception(message);}
    static void Refuse<T>(Action action) where T:Exception{try{action();}catch(T){return;}throw new Exception("Expected "+typeof(T).Name);}
    static int Main(string[] args)
    {
        var root=Path.GetFullPath(args[0]);Directory.CreateDirectory(root);var results=new List<object>();int failed=0;
        void Test(string name,Action<string> run){var watch=Stopwatch.StartNew();try{var dir=Path.Combine(root,name);Directory.CreateDirectory(dir);run(dir);results.Add(new{name,passed=true,ms=watch.ElapsedMilliseconds});Console.WriteLine("PASS "+name+" "+watch.ElapsedMilliseconds+"ms");}catch(Exception ex){failed++;results.Add(new{name,passed=false,error=ex.ToString()});Console.WriteLine("FAIL "+name+" "+ex.Message);}}
        Test("default-budget-passes-previous-count-limits",dir=>{var b=new ScanBudget();for(int i=0;i<150_000;i++)b.Visit(Path.Combine(dir,"Game"+i,"Game.exe"),false);});
        Test("memory-pressure-still-stops",dir=>{var b=new ScanBudget(maxManagedBytes:1);Refuse<ScanLimitException>(()=>{for(int i=0;i<4096;i++)b.Visit(Path.Combine(dir,"file"),false);});});
        Test("real-folders-over-500-complete",dir=>{for(int i=0;i<650;i++){var folder=Path.Combine(dir,"Game"+i);Directory.CreateDirectory(folder);File.WriteAllText(Path.Combine(folder,"Game.exe"),"harmless generated fixture; never execute");}var scan=GameScanner.Scan(dir,budget:new ScanBudget());Check(GameScanner.CandidateGroups(scan).Count()==650,"Stopped at prior limit");var prepared=ScanPreparation.Build(scan,[],[],[],Path.Combine(root,"library"),CancellationToken.None);Check(prepared.Packages.Count==650&&prepared.Checkpoints.Count==650,"Preparation omitted games");});
        Test("index-boundary-case-and-nested-exclusion",dir=>{var scan=new ScanSnapshot{Root=dir};var parent=Path.Combine(dir,"Game1");foreach(var path in new[]{parent,Path.Combine(parent,"Data"),Path.Combine(parent,"Other"),Path.Combine(dir,"Game10")})scan.Directories.Add(path);foreach(var path in new[]{Path.Combine(parent,"Game.exe"),Path.Combine(parent,"Data","a.dat"),Path.Combine(parent,"Other","Other.exe"),Path.Combine(dir,"Game10","Wrong.exe")})scan.Files.Add(new(path,7,DateTime.UtcNow));var p=new Package{Source=parent,Id=Guid.NewGuid().ToString("N"),OmittedFolders=["Other"]};var before=WorkspaceReconciler.Capture(p,scan);scan.PrepareIndex();var after=WorkspaceReconciler.Capture(p,scan);Check(before.Files.Select(f=>f.RelativePath).SequenceEqual(after.Files.Select(f=>f.RelativePath))&&before.Directories.SequenceEqual(after.Directories),"Indexed capture changed inclusion");Check(scan.FilesUnder(parent.ToUpperInvariant()).Count()==3&&scan.FilesUnder(parent+Path.DirectorySeparatorChar).Count()==3,"Prefix crossed folder boundary");});
        Test("index-invalidation-and-file-count-change",dir=>{var scan=new ScanSnapshot{Root=dir};scan.Directories.Add(dir);scan.Files.Add(new(Path.Combine(dir,"A.exe"),1,DateTime.UtcNow));scan.PrepareIndex();scan.Files[0]=new(Path.Combine(dir,"B.exe"),2,DateTime.UtcNow);scan.InvalidateIndex();Check(scan.FilesUnder(dir).Single().Length==2,"Stale replacement");scan.PrepareIndex();scan.Files.Add(new(Path.Combine(dir,"C.exe"),3,DateTime.UtcNow));Check(scan.FilesUnder(dir).Count()==2,"Count change ignored");});
        Test("indexed-capture-and-check-match-reference",dir=>{var scan=new ScanSnapshot{Root=dir};var p=new Package{Source=Path.Combine(dir,"Game"),Id=Guid.NewGuid().ToString("N")};scan.Directories.Add(p.Source);scan.Files.Add(new(Path.Combine(p.Source,"Game.exe"),1,DateTime.UtcNow));var baseline=WorkspaceReconciler.Capture(p,scan);scan.PrepareIndex();WorkspaceReconciler.Check(p,baseline,scan);Check(p.ReviewState=="","Unchanged game flagged");scan.Files.Add(new(Path.Combine(p.Source,"new.txt"),3,DateTime.UtcNow));scan.PrepareIndex();WorkspaceReconciler.Check(p,baseline,scan);Check(p.ReviewState=="changed"&&p.ReviewDetails.Count==1,"Change ignored");});
        Test("ten-thousand-candidates-and-120k-files",dir=>{var scan=new ScanSnapshot{Root=dir};scan.SearchRoots.Add(dir);scan.Directories.Add(dir);for(int i=0;i<10_000;i++){var folder=Path.Combine(dir,"Game"+i.ToString("D5"));scan.Directories.Add(folder);for(int n=0;n<12;n++)scan.Files.Add(new(Path.Combine(folder,n==0?"Game.exe":n+".dat"),n+1,DateTime.UnixEpoch));}var prepared=ScanPreparation.Build(scan,[],[],[],Path.Combine(dir,"library"),CancellationToken.None);Check(prepared.Packages.Count==10_000&&prepared.Checkpoints.Sum(c=>c.Files.Count)==120_000,"Large result incomplete");Check(prepared.Packages.All(p=>p.Size=="78 B"),"Sizes incorrect");var again=ScanPreparation.Build(scan,prepared.Packages,prepared.Checkpoints,[],Path.Combine(dir,"library"),CancellationToken.None);Check(again.Packages.Count==10_000&&again.Packages.All(p=>p.ReviewState.Length==0),"Rescan duplicates or flags games");});
        Test("pre-cancelled-large-preparation",dir=>{var scan=new ScanSnapshot{Root=dir};using var c=new CancellationTokenSource();c.Cancel();Refuse<OperationCanceledException>(()=>ScanPreparation.Build(scan,[],[],[],Path.Combine(dir,"library"),c.Token));});
        File.WriteAllText(args[1],JsonSerializer.Serialize(new{total=results.Count,passed=results.Count-failed,failed,results},new JsonSerializerOptions{WriteIndented=true}));return failed==0?0:1;
    }
}
